import{_ as t,o as a,c as i,ag as e}from"./chunks/framework.CtWPcAmt.js";const u=JSON.parse('{"title":"附录 E：Skill 设计检查表","description":"创建 Skill 前/中/后的检查清单，判断「该不该建」、四件套是否齐全、发布前安全审查。","frontmatter":{"title":"附录 E：Skill 设计检查表","description":"创建 Skill 前/中/后的检查清单，判断「该不该建」、四件套是否齐全、发布前安全审查。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"appendix/04-skill-checklist.md","filePath":"appendix/04-skill-checklist.md","lastUpdated":null}'),r={name:"appendix/04-skill-checklist.md"};function d(o,l,h,n,s,c){return a(),i("div",null,[...l[0]||(l[0]=[e('<h1 id="附录-e-skill-设计检查表" tabindex="-1">附录 E：Skill 设计检查表 <a class="header-anchor" href="#附录-e-skill-设计检查表" aria-label="Permalink to &quot;附录 E：Skill 设计检查表&quot;">​</a></h1><h2 id="一、建之前-该不该建-对应第-13-章" tabindex="-1">一、建之前：该不该建？（对应第 13 章） <a class="header-anchor" href="#一、建之前-该不该建-对应第-13-章" aria-label="Permalink to &quot;一、建之前：该不该建？（对应第 13 章）&quot;">​</a></h2><ul><li>[ ] 同一类任务已重复 ≥3 次？</li><li>[ ] 每次都要大量重复解释（指令长且固定）？</li><li>[ ] 任务结构稳定（不会每周大变）？</li><li>[ ] 普通模板（第 12 章）已经不够用？（需要带脚本/参考资料/跨任务调用）</li><li>[ ] 我能花 30–60 分钟做最小版并验证？</li></ul><p>全部 ✅ 才建；任一 ❌，先回去用模板或提示词。</p><h2 id="二、四件套检查-建的时候" tabindex="-1">二、四件套检查（建的时候） <a class="header-anchor" href="#二、四件套检查-建的时候" aria-label="Permalink to &quot;二、四件套检查（建的时候）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>检查项</th></tr></thead><tbody><tr><td>指令</td><td>[ ] 步骤化（角色 → 步骤 → 规则 → 输出格式）<br>[ ] 有自检要求（输出前检查什么）<br>[ ] 有「禁止事项」（不编造、不越界）</td></tr><tr><td>参考资料</td><td>[ ] 模板/示例已收进技能包<br>[ ] 适用范围已写明（适用/不适用）</td></tr><tr><td>脚本（可选）</td><td>[ ] 脚本内容已审查（会在 Agent 环境执行）<br>[ ] 无硬编码密钥/绝对路径</td></tr><tr><td>资源</td><td>[ ] 需要的文件已打包<br>[ ] 命名清晰（如 weekly-report）</td></tr></tbody></table><h2 id="三、调用验证-发布前" tabindex="-1">三、调用验证（发布前） <a class="header-anchor" href="#三、调用验证-发布前" aria-label="Permalink to &quot;三、调用验证（发布前）&quot;">​</a></h2><ul><li>[ ] 用真实任务调用一次，走通「输入 → 输出」；</li><li>[ ] 输出结构符合预期（模板生效）；</li><li>[ ] 连续调用 2–3 次，行为稳定；</li><li>[ ] 记录 v1.0 版本与「本次改动」；</li><li>[ ] 失败路径：输入异常时 Skill 会不会报错或编造？有没有兜底说明？</li></ul><h2 id="四、安全审查-分享-发布前" tabindex="-1">四、安全审查（分享/发布前） <a class="header-anchor" href="#四、安全审查-分享-发布前" aria-label="Permalink to &quot;四、安全审查（分享/发布前）&quot;">​</a></h2><ul><li>[ ] 无 API Key、Token、账号、密码（用变量或环境配置）；</li><li>[ ] 无个人信息、内部路径、公司机密；</li><li>[ ] 无不明来源脚本；</li><li>[ ] 无诱导越权的内容（如「绕过权限」「自动发送」）；</li><li>[ ] 已脱敏示例数据。</li></ul><h2 id="五、迭代维护" tabindex="-1">五、迭代维护 <a class="header-anchor" href="#五、迭代维护" aria-label="Permalink to &quot;五、迭代维护&quot;">​</a></h2><ul><li>[ ] 每次使用后记录「不适用/没说清」的点；</li><li>[ ] 版本号 +1 并写改动（v1.1：修改了…）；</li><li>[ ] 三个月没用的 Skill：评估是删除还是升级；</li><li>[ ] 规则/口径变化时同步更新 Skill 内引用（与第 14 章记忆淘汰联动）。</li></ul><h2 id="最小可用提醒" tabindex="-1">最小可用提醒 <a class="header-anchor" href="#最小可用提醒" aria-label="Permalink to &quot;最小可用提醒&quot;">​</a></h2><p>第一个 Skill 从「指令 + 一个模板」开始就够；脚本和资源是加分项，不是必需。<strong>能跑通、能验证、能迭代，就是合格的最小 Skill。</strong></p>',14)])])}const p=t(r,[["render",d]]);export{u as __pageData,p as default};
